mapper.select:
SELECT s.id, a.parking_lot_id, s.area_id, a.area_code, s.space_code, s.description, s.status, s.created_at, s.updated_at FROM parking_space s JOIN parking_area a ON a.id = s.area_id WHERE a.parking_lot_id = #{lotId}
AND s.area_id = #{areaId}
AND s.status = #{status}
ORDER BY a.area_code, s.space_code, s.id

SELECT COUNT(*)
FROM parking_space
WHERE area_id = #{areaId}
  AND space_code = #{spaceCode}

SELECT COUNT(*)
FROM parking_record
WHERE parking_space_id = #{spaceId}

mapper.update:
UPDATE parking_space
SET status     = #{status},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = #{expectedStatus}

mapper.delete:
DELETE FROM parking_space
WHERE id = #{id}
  AND status = 'FREE'
